1	package posemap
2	
3	import (
4		"errors"
5		"fmt"
6		"sort"
7		"sync"
8	)
9	
10	// Map 是一份带持久化文件的二维轨迹与路标地图。零值不可用，须经 Create
11	// 或 Open 得到。单个 Map 可被多个 goroutine 并发使用。
12	type Map struct {
13		mu     sync.Mutex
14		path   string
15		state  *mapState
16		closed bool
17	}
18	
19	// mapState 是地图的全部内存状态。
20	type mapState struct {
21		config       Config
22		trajectory   []Pose // 按时间严格递增；trajectory[0] 为初始位姿
23		landmarks    map[string]*landmarkState
24		segments     map[string]*segmentRecord
25		sources      []*frameSource // sources[k] 对应 trajectory[k+1]；长度恒为 len(trajectory)-1
26		corrections  []*CorrectionRecord
27		corrIndex    map[string]string              // 校正标识 -> 首次内容指纹
28		invalRecords []*invalidationRecord          // 按提交次序的成功失效操作
29		invalIndex   map[string]*invalidationRecord // 失效标识 -> 首次记录
30	}
31	
32	// frameSource 是生成某一帧的原始输入，供回环校正重放路标观测与累计
33	// 原运动方差。该切片中的 nil 元素表示对应帧来自不携带逐帧依据的旧
34	// 文件，涉及它的历史范围不能校正。
35	type frameSource struct {
36		moveVariance float64
37		observations []Observation
38	}
39	
40	// landmarkState 是同一标识历次出现的聚合状态。appearances 按出现编号
41	// 递增保存（编号即下标+1）；最后一次出现可能仍为当前有效记录，也可能
42	// 已被失效。失效后的旧出现不参与新观测的合并；下一次出现从编号 1 起的
43	// 全新记录开始，观测计数从 1 计起。
44	//
45	// legacy* 只用于打开不携带逐帧观测来源的旧文件：旧文件中每一帧的观测
46	// 无法重放，因此旧文件第 1 次出现的全部观测贡献视为固定的 legacyCount
47	// 次平均，不随后续校正改变；旧文件之后新导入且依据完整的观测再做增量
48	// 平均。由本版本创建/导入的出现 legacyCount 为 0，全部观测均可重放。
49	type landmarkState struct {
50		appearances []*occurrenceState
51	}
52	
53	// occurrenceState 是某一标识某一次出现的状态。
54	type occurrenceState struct {
55		x             float64
56		y             float64
57		count         int
58		legacyCount   int
59		legacyMX      float64
60		legacyMY      float64
61		firstSeenTime int64 // 首次观测所在帧时间
62		hasFirstSeen  bool  // 旧文件缺少来源时为假
63		active        bool  // 是否为当前有效记录
64		invalidTime   int64 // 失效时间（提交时当前位姿时间）
65		invalidReason string
66		invalidOpID   string
67	}
68	
69	// activeOccurrence 返回当前有效记录；不存在（从未出现或最近一次已失效）
70	// 时返回 nil。
71	func (lm *landmarkState) activeOccurrence() *occurrenceState {
72		if len(lm.appearances) == 0 {
73			return nil
74		}
75		last := lm.appearances[len(lm.appearances)-1]
76		if !last.active {
77			return nil
78		}
79		return last
80	}
81	
82	// invalidationRecord 记录一次成功失效操作的首次内容与结果，供相同操作
83	// 标识以相同原因、相同路标集合重复提交时直接返回。
84	type invalidationRecord struct {
85		id     string
86		reason string
87		hash   string // 路标集合（排序后）的指纹
88		result InvalidationResult
89	}
90	
91	// segmentRecord 记录一个已成功保存的段：内容指纹与首次导入结果，
92	// 供相同内容重复导入时直接返回。
93	type segmentRecord struct {
94		hash   string
95		result ImportResult
96	}
97	
98	// ImportResult 是一次成功段导入的结果：本段末位姿及方差，以及本段
99	// 涉及（观测到）的全部路标标识（去重、按标识排序）。
100	type ImportResult struct {
101		EndPose     Pose
102		LandmarkIDs []string
103	}
104	
105	// Create 在 path 处创建一份新地图并写入初始文件。path 已存在时返回
106	// 错误，以免覆盖既有数据（既有地图请用 Open）。
107	func Create(path string, cfg Config) (*Map, error) {
108		if err := validateConfig(cfg); err != nil {
109			return nil, err
110		}
111		st := &mapState{
112			config:       cfg,
113			trajectory:   []Pose{{Time: cfg.InitialTime, X: cfg.InitialX, Y: cfg.InitialY, Heading: cfg.InitialHeading, Variance: cfg.InitialVariance}},
114			landmarks:    make(map[string]*landmarkState),
115			segments:     make(map[string]*segmentRecord),
116			corrIndex:    make(map[string]string),
117			invalRecords: nil,
118			invalIndex:   make(map[string]*invalidationRecord),
119		}
120		m := &Map{path: path, state: st}
121		// O_EXCL：目标已存在即失败，绝不当作新地图覆盖。
122		if err := m.saveExclusive(); err != nil {
123			return nil, err
124		}
125		return m, nil
126	}
127	
128	// Open 打开 path 处由 Create/导入生成的地图文件。文件不存在时返回
129	// 包装了 fs.ErrNotExist 的错误；文件损坏返回可 errors.Is(ErrCorrupt)
130	// 的错误；格式版本不支持返回 ErrUnsupportedVersion。Open 绝不覆盖
131	// 无法识别的文件。
132	func Open(path string) (*Map, error) {
133		st, err := loadFile(path)
134		if err != nil {
135			return nil, err
136		}
137		return &Map{path: path, state: st}, nil
138	}
139	
140	// Path 返回地图对应的本地数据文件路径。
141	func (m *Map) Path() string {
142		m.mu.Lock()
143		defer m.mu.Unlock()
144		return m.path
145	}
146	
147	// Close 关闭地图。每次成功导入都已落盘，Close 本身不修改数据文件；
148	// 关闭后再调用其他方法返回 ErrClosed。
149	func (m *Map) Close() error {
150		m.mu.Lock()
151		defer m.mu.Unlock()
152		m.closed = true
153		return nil
154	}
155	
156	func validateConfig(cfg Config) error {
157		switch {
158		case !isFinite(cfg.InitialX) || !isFinite(cfg.InitialY) || !isFinite(cfg.InitialHeading):
159			return fmt.Errorf("%w: non-finite initial pose", ErrInvalidConfig)
160		case !isFinite(cfg.InitialVariance) || cfg.InitialVariance < 0:
161			return fmt.Errorf("%w: initial variance must be non-negative and finite", ErrInvalidConfig)
162		case cfg.MaxInterval <= 0:
163			return fmt.Errorf("%w: max interval must be positive", ErrInvalidConfig)
164		case !isFinite(cfg.MergeDistance) || cfg.MergeDistance <= 0:
165			return fmt.Errorf("%w: merge distance must be positive and finite", ErrInvalidConfig)
166		default:
167			return nil
168		}
169	}
170	
171	// ImportSegment 导入一批带非空段标识的有序帧。
172	//
173	// 整段要么全部生效（含落盘），要么因可区分的 *RejectError 被整段拒绝，
174	// 此前已提交的位姿、路标、观测次数不受影响。输入本身全为有限数值并不保证
175	// 推演结果有限：运动完成后的位置、朝向、累计位置方差，或某条观测转换到
176	// 地图坐标后的位置若出现 NaN/无穷值，仍以 RejectNonFinite 拒绝产生异常
177	// 的帧（从零开始的帧序号；路标坐标异常时携带路标标识），不会留到保存时
178	// 才以普通编码错误失败。已成功保存的段标识再次以
179	// 相同内容导入时，直接返回首次导入的结果且不改变当前数据；同一标识
180	// 对应不同内容则以 RejectDuplicateMismatch 拒绝。
181	func (m *Map) ImportSegment(seg Segment) (ImportResult, error) {
182		m.mu.Lock()
183		defer m.mu.Unlock()
184		if m.closed {
185			return ImportResult{}, ErrClosed
186		}
187		st := m.state
188	
189		if seg.ID == "" {
190			return ImportResult{}, &RejectError{Kind: RejectEmptyID}
191		}
192		if len(seg.Frames) == 0 {
193			return ImportResult{}, &RejectError{Kind: RejectEmptySegment}
194		}
195	
196		// 已保存段：相同内容直接返回首次结果；不同内容明确拒绝。
197		// 不做任何校验或状态变更，即使其后又导入过其他段。
198		if rec, ok := st.segments[seg.ID]; ok {
199			if canonicalHash(seg.Frames) == rec.hash {
200				return cloneResult(rec.result), nil
201			}
202			return ImportResult{}, &RejectError{Kind: RejectDuplicateMismatch, Landmark: seg.ID, HasLandmark: true}
203		}
204	
205		// ---- 在暂存区上校验并推演，真实状态此时保持不变 ----
206		cur := st.trajectory[len(st.trajectory)-1]
207		prevTime := cur.Time
208		newPoses := make([]Pose, 0, len(seg.Frames))
209		// staged 记录本帧触及路标的暂存聚合：agg 按统一规则（见 aggregate.go）
210		// 维护本段内逐条接纳观测的等权平均位置与计数；created 为真表示这是本段
211		// 首条观测产生的新出现（此前不存在当前有效记录），firstSeen 为该出现首
212		// 条观测所在帧时间。
213		type stagedLM struct {
214			agg       observationAgg
215			created   bool
216			firstSeen int64
217		}
218		staged := make(map[string]stagedLM) // 本段触及路标的暂存聚合
219		touched := make(map[string]struct{})
220	
221		reject := func(kind string, frame int) (ImportResult, error) {
222			return ImportResult{}, &RejectError{Kind: kind, Frame: frame, HasFrame: true}
223		}
224	
225		for i, f := range seg.Frames {
226			// 时间：严格递增；首帧必须晚于初始时间或上一段末帧。
227			if f.Time <= prevTime {
228				return reject(RejectTimeOrder, i)
229			}
230			// 相邻位姿间隔上限。时间以有符号 int64 毫秒表示且允许负值，
231			// f.Time-prevTime 在 prevTime 接近 math.MinInt64 而 f.Time 为正时
232			// 会溢出回绕成负数，把实际超限的大缺口放过去。此处已保证
233			// f.Time > prevTime，真实差值必落在 [1, 2^64-1]，用无符号减法
234			// 得到精确的数学差值再与上限比较（MaxInterval 已校验为正）。
235			if uint64(f.Time)-uint64(prevTime) > uint64(m.state.config.MaxInterval) {
236				return reject(RejectInterval, i)
237			}
238			// 运动数值有限、方差非负。
239			if !isFinite(f.DX) || !isFinite(f.DY) || !isFinite(f.DHeading) || !isFinite(f.MoveVariance) {
240				return reject(RejectNonFinite, i)
241			}
242			if f.MoveVariance < 0 {
243				return reject(RejectNegativeVariance, i)
244			}
245			// 观测标识非空、观测位置有限。
246			for _, ob := range f.Observations {
247				if ob.ID == "" {
248					return reject(RejectEmptyID, i)
249				}
250				if !isFinite(ob.X) || !isFinite(ob.Y) {
251					return ImportResult{}, &RejectError{Kind: RejectNonFinite, Frame: i, HasFrame: true, Landmark: ob.ID, HasLandmark: true}
252				}
253			}
254	
255			// 运动：先按运动前朝向把平移转换到地图坐标，再更新朝向并归一。
256			nx, ny := localToMap(cur.X, cur.Y, cur.Heading, f.DX, f.DY)
257			cur = Pose{
258				Time:     f.Time,
259				X:        nx,
260				Y:        ny,
261				Heading:  normalizeAngle(cur.Heading + f.DHeading),
262				Variance: cur.Variance + f.MoveVariance,
263			}
264			// 输入本身有限并不保证结果有限：位置叠加、朝向累计或方差累计
265			// 仍可能溢出为无穷（例如 1e308 再前进 1e308）。按数值异常拒绝
266			// 产生异常的这一帧，而不是等到保存时得到普通编码错误。
267			if !isFinite(cur.X) || !isFinite(cur.Y) || !isFinite(cur.Heading) || !isFinite(cur.Variance) {
268				return reject(RejectNonFinite, i)
269			}
270			newPoses = append(newPoses, cur)
271	
272			// 观测按运动完成后的位姿转换到地图坐标，同帧按输入次序逐条处理；
273			// 接纳与合并规则与回环校正重放共享同一实现（见 aggregate.go）。
274			for _, ob := range f.Observations {
275				s, seen := staged[ob.ID]
276				if !seen {
277					if lm := st.landmarks[ob.ID]; lm != nil {
278						if active := lm.activeOccurrence(); active != nil {
279							// 以当前有效出现的已提交观测为固定起点，本段观测在
280							// 其当前均值上增量合并；暂存不修改真实状态。旧出现
281							// （已失效）永不参与新观测的合并。
282							s.agg.seed(active.count, active.x, active.y)
283						}
284					}
285					if s.agg.count == 0 {
286						// 从未出现或最近一次已失效：本次为新的一次出现，编号在
287						// 提交时确定，首条观测计数从 1 开始。
288						s.created = true
289						s.firstSeen = f.Time
290					}
291				}
292				// 转换、非有限优先、首条建点、距离判定（恰含上限）、增量平均
293				// 与计数全部走统一规则。
294				switch s.agg.admit(cur, ob, st.config.MergeDistance) {
295				case obsNonFinite:
296					// 转换结果可能因位姿/观测坐标过大而溢出：无论该路标是首次
297					// 出现、失效后再次出现，还是与有效记录合并，数值异常都优先
298					// 于距离冲突，按同一原因拒绝并携带路标标识。
299					return ImportResult{}, &RejectError{Kind: RejectNonFinite, Frame: i, HasFrame: true, Landmark: ob.ID, HasLandmark: true}
300				case obsConflict:
301					return ImportResult{}, &RejectError{Kind: RejectLandmarkConflict, Frame: i, HasFrame: true, Landmark: ob.ID, HasLandmark: true}
302				}
303				staged[ob.ID] = s
304				touched[ob.ID] = struct{}{}
305			}
306	
307			prevTime = f.Time
308		}
309	
310		ids := make([]string, 0, len(touched))
311		for id := range touched {
312			ids = append(ids, id)
313		}
314		sort.Strings(ids)
315		res := ImportResult{EndPose: cur, LandmarkIDs: ids}
316	
317		// 逐帧依据（原运动方差与原始观测）与位姿一一对应，供以后的回环
318		// 校正重放。
319		newSources := make([]*frameSource, len(seg.Frames))
320		for i, f := range seg.Frames {
321			obs := append([]Observation(nil), f.Observations...)
322			newSources[i] = &frameSource{moveVariance: f.MoveVariance, observations: obs}
323		}
324	
325		// ---- 全部校验通过：提交内存状态并落盘；落盘失败精确回滚 ----
326		trajLenBefore := len(st.trajectory)
327		srcLenBefore := len(st.sources)
328		type undoLandmark struct {
329			lm       *landmarkState
330			ok       bool
331			created  bool
332			replaced *occurrenceState // 非新建时被暂存副本替换掉的原当前出现
333		}
334		undo := make(map[string]undoLandmark, len(staged))
335		for id, s := range staged {
336			old, ok := st.landmarks[id]
337			if s.created {
338				// 新的一次出现：可能是该标识的首次出现，也可能接在已失效的
339				// 历次出现之后。编号即追加后的切片长度；位置/计数取自暂存聚合。
340				occ := &occurrenceState{
341					x: s.agg.x, y: s.agg.y, count: s.agg.count,
342					firstSeenTime: s.firstSeen, hasFirstSeen: true,
343					active: true,
344				}
345				lm := old
346				if lm == nil {
347					lm = &landmarkState{}
348				}
349				lm.appearances = append(lm.appearances, occ)
350				st.landmarks[id] = lm
351				undo[id] = undoLandmark{lm: old, ok: ok, created: true}
352			} else {
353				// 更新既有当前有效出现：复制原出现（保留固定旧贡献等元数据），
354				// 仅把位置与计数换成暂存聚合结果，再以副本替换原指针，旧出现
355				// 原样保留。
356				src := old.appearances[len(old.appearances)-1]
357				occ := *src
358				occ.x, occ.y, occ.count = s.agg.x, s.agg.y, s.agg.count
359				replaced := src
360				old.appearances[len(old.appearances)-1] = &occ
361				undo[id] = undoLandmark{lm: old, ok: ok, created: false, replaced: replaced}
362			}
363		}
364		st.trajectory = append(st.trajectory, newPoses...)
365		st.sources = append(st.sources, newSources...)
366		st.segments[seg.ID] = &segmentRecord{hash: canonicalHash(seg.Frames), result: cloneResult(res)}
367	
368		if err := m.saveReplace(); err != nil {
369			st.trajectory = st.trajectory[:trajLenBefore]
370			st.sources = st.sources[:srcLenBefore]
371			for id, u := range undo {
372				switch {
373				case !u.ok:
374					delete(st.landmarks, id)
375				case u.created:
376					u.lm.appearances = u.lm.appearances[:len(u.lm.appearances)-1]
377				default:
378					u.lm.appearances[len(u.lm.appearances)-1] = u.replaced
379				}
380			}
381			delete(st.segments, seg.ID)
382			return ImportResult{}, err
383		}
384		return res, nil
385	}
386	
387	func cloneResult(r ImportResult) ImportResult {
388		ids := make([]string, len(r.LandmarkIDs))
389		copy(ids, r.LandmarkIDs)
390		r.LandmarkIDs = ids
391		return r
392	}
393	
394	// CurrentPose 返回当前位姿及其位置方差；尚无帧导入时返回初始位姿。
395	func (m *Map) CurrentPose() (Pose, error) {
396		m.mu.Lock()
397		defer m.mu.Unlock()
398		if m.closed {
399			return Pose{}, ErrClosed
400		}
401		return m.state.trajectory[len(m.state.trajectory)-1], nil
402	}
403	
404	// PoseAt 返回不晚于 t 的最后一份历史位姿及其方差。t 早于初始时间时
405	// 返回 ErrNotFound。
406	func (m *Map) PoseAt(t int64) (Pose, error) {
407		m.mu.Lock()
408		defer m.mu.Unlock()
409		if m.closed {
410			return Pose{}, ErrClosed
411		}
412		tr := m.state.trajectory
413		// j 为第一个时间 > t 的位置。
414		j := sort.Search(len(tr), func(j int) bool { return tr[j].Time > t })
415		if j == 0 {
416			return Pose{}, ErrNotFound
417		}
418		return tr[j-1], nil
419	}
420	
421	// Rect 描述一个包含边界的轴对齐矩形查询区域，单位米。
422	type Rect struct {
423		MinX, MinY, MaxX, MaxY float64
424	}
425	
426	// LandmarksInRect 返回矩形（含边界）内当前仍有效路标的最新一次出现及
427	// 观测次数，按标识排序；已失效（且尚未再次出现）的路标立即排除，区域为
428	// 空时返回非 nil 的空切片。上下界颠倒或含非有限值时报 ErrInvalidRect。
429	func (m *Map) LandmarksInRect(r Rect) ([]Landmark, error) {
430		m.mu.Lock()
431		defer m.mu.Unlock()
432		if m.closed {
433			return nil, ErrClosed
434		}
435		if !isFinite(r.MinX) || !isFinite(r.MinY) || !isFinite(r.MaxX) || !isFinite(r.MaxY) ||
436			r.MinX > r.MaxX || r.MinY > r.MaxY {
437			return nil, fmt.Errorf("%w: min bounds must not exceed max bounds and all values must be finite", ErrInvalidRect)
438		}
439		var out []Landmark
440		for id, lm := range m.state.landmarks {
441			occ := lm.activeOccurrence()
442			if occ == nil {
443				continue // 最近一次出现已失效：立即排除。
444			}
445			if occ.x >= r.MinX && occ.x <= r.MaxX && occ.y >= r.MinY && occ.y <= r.MaxY {
446				out = append(out, Landmark{ID: id, X: occ.x, Y: occ.y, Count: occ.count})
447			}
448		}
449		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
450		if out == nil {
451			out = []Landmark{}
452		}
453		return out, nil
454	}
455	
456	// AsRejectError 返回错误对应的 *RejectError；不是段拒绝错误时返回 nil、false。
457	func AsRejectError(err error) (*RejectError, bool) {
458		var r *RejectError
459		if errors.As(err, &r) {
460			return r, true
461		}
462		return nil, false
463	}
