109	type corrRecJSON struct {
110		ID        string               `json:"id"`
111		Anchor    int64                `json:"anchor"`
112		Target    CorrectionTarget     `json:"target"`
113		EndTime   int64                `json:"end_time"`
114		Poses     []poseChangeJSON     `json:"poses"`
115		Landmarks []landmarkChangeJSON `json:"landmarks"`
