118	// encodeFile 把内存状态编码为完整文件字节。
119	func encodeFile(st *mapState) ([]byte, error) {
120		fd := fileData{
121			Version:       int(fileVersion),
122			Config:        st.config,
123			Trajectory:    st.trajectory,
124			Landmarks:     make([]landmarkJSON, 0, len(st.landmarks)),
125			Segments:      make([]segmentJSON, 0, len(st.segments)),
126			Sources:       make([]*frameSrcJSON, len(st.sources)),
127			Corrections:   make([]corrRecJSON, 0, len(st.corrections)),
128			Invalidations: make([]invalJSON, 0, len(st.invalRecords)),
129		}
130		for id, lm := range st.landmarks {
131			lj := landmarkJSON{ID: id, Occurrences: make([]occurrenceJSON, 0, len(lm.appearances))}
132			for i, occ := range lm.appearances {
133				oj := occurrenceJSON{
134					Number:        i + 1,
135					X:             occ.x,
136					Y:             occ.y,
137					Count:         occ.count,
138					LegacyCount:   occ.legacyCount,
139					LegacyMX:      occ.legacyMX,
140					LegacyMY:      occ.legacyMY,
141					FirstSeenTime: occ.firstSeenTime,
142					HasFirstSeen:  occ.hasFirstSeen,
143					Active:        occ.active,
144				}
145				if !occ.active {
146					oj.InvalidTime = occ.invalidTime
147					oj.InvalidReason = occ.invalidReason
148					oj.InvalidOpID = occ.invalidOpID
149				}
150				lj.Occurrences = append(lj.Occurrences, oj)
151			}
152			fd.Landmarks = append(fd.Landmarks, lj)
153		}
154		for id, rec := range st.segments {
155			fd.Segments = append(fd.Segments, segmentJSON{ID: id, Hash: rec.hash, Result: rec.result})
156		}
157		for k, src := range st.sources {
158			if src == nil {
159				continue // 旧文件帧在新文件中保留为 null，表示仍无逐帧依据
160			}
161			obs := append([]Observation(nil), src.observations...)
162			fd.Sources[k] = &frameSrcJSON{MoveVariance: src.moveVariance, Observations: obs}
163		}
164		for _, rec := range st.corrections {
165			cj := corrRecJSON{
166				ID:        rec.ID,
167				Anchor:    rec.Anchor,
168				Target:    rec.Target,
169				EndTime:   rec.EndTime,
170				Poses:     make([]poseChangeJSON, len(rec.Poses)),
171				Landmarks: make([]landmarkChangeJSON, len(rec.Landmarks)),
172			}
173			for i, pc := range rec.Poses {
174				cj.Poses[i] = poseChangeJSON{Before: pc.Before, After: pc.After}
175			}
176			for i, lc := range rec.Landmarks {
177				cj.Landmarks[i] = landmarkChangeJSON{ID: lc.ID, Occurrence: lc.Occurrence, Before: lc.Before, After: lc.After}
178			}
179			fd.Corrections = append(fd.Corrections, cj)
180		}
181		for _, rec := range st.invalRecords {
182			ij := invalJSON{
183				ID:        rec.id,
184				Reason:    rec.reason,
185				Hash:      rec.hash,
186				Time:      rec.result.Time,
187				Landmarks: make([]invalLMJSON, len(rec.result.Landmarks)),
188			}
189			for i, l := range rec.result.Landmarks {
190				ij.Landmarks[i] = invalLMJSON{ID: l.ID, Occurrence: l.Occurrence}
191			}
192			fd.Invalidations = append(fd.Invalidations, ij)
193		}
194		payload, err := json.Marshal(&fd)
195		if err != nil {
196			return nil, fmt.Errorf("posemap: encode state: %w", err)
197		}
198	
199		out := make([]byte, headerLen+len(payload)+4)
200		copy(out[0:8], fileMagic)
201		binary.BigEndian.PutUint16(out[8:10], fileVersion)
202		binary.BigEndian.PutUint32(out[10:14], uint32(len(payload)))
203		copy(out[headerLen:], payload)
204		sum := crc32.ChecksumIEEE(out[:headerLen+len(payload)])
205		binary.BigEndian.PutUint32(out[headerLen+len(payload):], sum)
206		return out, nil
207	}
208	
209	// loadFile 只读取证地解析地图文件。
210	func loadFile(path string) (*mapState, error) {
211		raw, err := os.ReadFile(path)
212		if err != nil {
213			return nil, err // 含 fs.ErrNotExist，交由调用方/上层用 errors.Is 判断
214		}
215		if len(raw) < headerLen+4 || string(raw[:8]) != fileMagic {
216			return nil, fmt.Errorf("%w: unrecognized header", ErrCorrupt)
217		}
218		version := binary.BigEndian.Uint16(raw[8:10])
219		if version != fileVersion {
220			return nil, fmt.Errorf("%w: version %d", ErrUnsupportedVersion, version)
221		}
222		length := binary.BigEndian.Uint32(raw[10:14])
223		if int(length) != len(raw)-headerLen-4 {
224			return nil, fmt.Errorf("%w: truncated or length mismatch", ErrCorrupt)
225		}
226		want := binary.BigEndian.Uint32(raw[len(raw)-4:])
227		if crc32.ChecksumIEEE(raw[:len(raw)-4]) != want {
228			return nil, fmt.Errorf("%w: checksum mismatch", ErrCorrupt)
229		}
230	
231		var fd fileData
232		if err := json.Unmarshal(raw[headerLen:headerLen+int(length)], &fd); err != nil {
233			return nil, fmt.Errorf("%w: %v", ErrCorrupt, err)
234		}
235		if err := validateLoaded(&fd); err != nil {
236			return nil, err
237		}
238	
239		st := &mapState{
240			config:       fd.Config,
241			trajectory:   fd.Trajectory,
242			landmarks:    make(map[string]*landmarkState, len(fd.Landmarks)),
243			segments:     make(map[string]*segmentRecord, len(fd.Segments)),
244			sources:      make([]*frameSource, len(fd.Trajectory)-1),
245			corrections:  make([]*CorrectionRecord, 0, len(fd.Corrections)),
246			corrIndex:    make(map[string]string, len(fd.Corrections)),
247			invalRecords: make([]*invalidationRecord, 0, len(fd.Invalidations)),
248			invalIndex:   make(map[string]*invalidationRecord, len(fd.Invalidations)),
249		}
250		// 旧文件不携带逐帧依据：有帧而 sources 缺省即旧地图。无帧时二者
251		// 无法区分也无需区分（尚无范围可校正）。
252		oldFormat := len(fd.Sources) == 0 && len(fd.Trajectory) > 1
253		for _, lmj := range fd.Landmarks {
254			lm := &landmarkState{}
255			if len(lmj.Occurrences) > 0 {
256				// 新格式：历次出现按编号递增保存。
257				for _, oj := range lmj.Occurrences {
258					lm.appearances = append(lm.appearances, &occurrenceState{
259						x:             oj.X,
260						y:             oj.Y,
261						count:         oj.Count,
262						legacyCount:   oj.LegacyCount,
263						legacyMX:      oj.LegacyMX,
264						legacyMY:      oj.LegacyMY,
265						firstSeenTime: oj.FirstSeenTime,
266						hasFirstSeen:  oj.HasFirstSeen,
267						active:        oj.Active,
268						invalidTime:   oj.InvalidTime,
269						invalidReason: oj.InvalidReason,
270						invalidOpID:   oj.InvalidOpID,
271					})
272				}
273			} else {
274				// 兼容旧布局：一个平铺路标即第 1 次有效出现。
275				occ := &occurrenceState{
276					x:      lmj.X,
277					y:      lmj.Y,
278					count:  lmj.Count,
279					active: true,
280				}
281				if oldFormat {
282					// 旧文件中该路标的全部既有观测都是固定旧贡献，位置取
283					// 文件中的聚合值；缺少逐帧来源，首次观测时间未知。
284					occ.legacyCount = lmj.Count
285					occ.legacyMX, occ.legacyMY = lmj.X, lmj.Y
286					occ.hasFirstSeen = false
287				} else {
288					occ.legacyCount = lmj.LegacyCount
289					occ.legacyMX, occ.legacyMY = lmj.LegacyMX, lmj.LegacyMY
290					// 含固定旧贡献时最早观测缺少来源，首次观测时间未知；
291					// 否则从逐帧依据中恢复该出现第一次被观测到的帧时间。
292					occ.hasFirstSeen = lmj.LegacyCount == 0
293					if occ.hasFirstSeen {
294						for k, src := range fd.Sources {
295							if src == nil {
296								continue
297							}
298							found := false
299							for _, ob := range src.Observations {
300								if ob.ID == lmj.ID {
301									found = true
302									break
303								}
304							}
305							if found {
306								occ.firstSeenTime = fd.Trajectory[k+1].Time
307								break
308							}
309						}
310					}
311				}
312				lm.appearances = append(lm.appearances, occ)
313			}
314			st.landmarks[lmj.ID] = lm
315		}
316		for _, sg := range fd.Segments {
317			ids := sg.Result.LandmarkIDs
318			if ids == nil {
319				ids = []string{}
320			}
321			st.segments[sg.ID] = &segmentRecord{
322				hash:   sg.Hash,
323				result: ImportResult{EndPose: sg.Result.EndPose, LandmarkIDs: ids},
324			}
325		}
326		if !oldFormat {
327			for k, src := range fd.Sources {
328				if src == nil {
329					continue // 来自旧文件的帧：保持依据缺失
330				}
331				obs := append([]Observation(nil), src.Observations...)
332				st.sources[k] = &frameSource{moveVariance: src.MoveVariance, observations: obs}
333			}
334		}
335		for _, cj := range fd.Corrections {
336			rec := &CorrectionRecord{
337				ID:        cj.ID,
338				Anchor:    cj.Anchor,
339				Target:    cj.Target,
340				EndTime:   cj.EndTime,
341				Poses:     make([]PoseChange, len(cj.Poses)),
342				Landmarks: make([]LandmarkChange, len(cj.Landmarks)),
343			}
344			for i, pc := range cj.Poses {
345				rec.Poses[i] = PoseChange{Before: pc.Before, After: pc.After}
346			}
347			for i, lc := range cj.Landmarks {
348				occNum := lc.Occurrence
349				if occNum == 0 {
350					occNum = 1 // 更早版本写出的校正记录不带编号，只有第 1 次出现
351				}
352				rec.Landmarks[i] = LandmarkChange{ID: lc.ID, Occurrence: occNum, Before: lc.Before, After: lc.After}
353			}
354			st.corrections = append(st.corrections, rec)
355			st.corrIndex[cj.ID] = canonicalCorrectionHash(cj.Anchor, cj.Target)
356		}
357		for _, ij := range fd.Invalidations {
358			lms := make([]InvalidatedLandmark, len(ij.Landmarks))
359			for i, l := range ij.Landmarks {
360				lms[i] = InvalidatedLandmark{ID: l.ID, Occurrence: l.Occurrence}
361			}
362			rec := &invalidationRecord{
363				id:     ij.ID,
364				reason: ij.Reason,
365				hash:   ij.Hash,
366				result: InvalidationResult{Time: ij.Time, Landmarks: lms},
367			}
368			st.invalRecords = append(st.invalRecords, rec)
369			st.invalIndex[ij.ID] = rec
370		}
371		return st, nil
372	}
373	
374	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
375	func validateLoaded(fd *fileData) error {
376		switch {
377		case fd.Version != int(fileVersion):
378			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
379		case len(fd.Trajectory) == 0:
380			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
381		}
382		if err := validateConfig(fd.Config); err != nil {
383			// 配置不合法不可能由本版本写出。
384			return fmt.Errorf("%w: %v", ErrCorrupt, err)
385		}
386		// 保存的整条轨迹必须满足与导入时相同的时间规则：从初始位姿起
387		// 时间严格递增，且相邻位姿的真实间隔不超过 MaxInterval（恰好
388		// 等于上限合法）。任何一处相等、倒退或超限都使按时间查询失去
389		// 可靠的先后依据，整份文件按损坏拒绝。间隔按真实差值判断：前
390		// 一时间接近 math.MinInt64 而后一时间为非负时，有符号减法会
391		// 溢出回绕成负数，把超限的巨大缺口放过去；此处已保证递增，真
392		// 实差值落在 [1, 2^64-1]，用无符号减法取精确的数学差值再与上
393		// 限比较（MaxInterval 已校验为正）。
394		for i := 1; i < len(fd.Trajectory); i++ {
395			prev, cur := fd.Trajectory[i-1].Time, fd.Trajectory[i].Time
396			if cur <= prev {
397				return fmt.Errorf("%w: trajectory time at pose %d is not strictly increasing", ErrCorrupt, i)
398			}
399			if uint64(cur)-uint64(prev) > uint64(fd.Config.MaxInterval) {
400				return fmt.Errorf("%w: trajectory interval between poses %d and %d exceeds max interval", ErrCorrupt, i-1, i)
401			}
402		}
403		// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
404		// 该字段（解码为 nil），数量为 0。
405		if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
406			return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
407		}
408		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
409		for _, lm := range fd.Landmarks {
410			if lm.ID == "" {
411				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
412			}
413			if _, dup := seenIDs[lm.ID]; dup {
414				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
415			}
416			seenIDs[lm.ID] = struct{}{}
417			if len(lm.Occurrences) == 0 {
418				// 兼容旧布局：平铺字段表示第 1 次出现。
419				if lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
420					return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
421				}
422				if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
423					return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
424				}
425				if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
426					return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
427				}
428				continue
429			}
430			activeCount := 0
431			for i, oj := range lm.Occurrences {
432				if oj.Number != i+1 || oj.Count < 1 || !isFinite(oj.X) || !isFinite(oj.Y) {
433					return fmt.Errorf("%w: invalid occurrence for landmark %s", ErrCorrupt, lm.ID)
434				}
435				if oj.LegacyCount < 0 || oj.LegacyCount > oj.Count {
436					return fmt.Errorf("%w: invalid legacy count for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
437				}
438				if oj.LegacyCount > 0 && (!isFinite(oj.LegacyMX) || !isFinite(oj.LegacyMY)) {
439					return fmt.Errorf("%w: invalid legacy mean for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
440				}
441				if oj.Active {
442					activeCount++
443					if i != len(lm.Occurrences)-1 {
444						return fmt.Errorf("%w: active occurrence %d of landmark %s is not the latest", ErrCorrupt, oj.Number, lm.ID)
445					}
446				} else if oj.InvalidReason == "" {
447					return fmt.Errorf("%w: invalidated occurrence %d of landmark %s lacks reason", ErrCorrupt, oj.Number, lm.ID)
448				}
449				// 出现编号即先后次序，各次出现接纳观测的时间范围必须与之
450				// 相容，否则同一观测可能同时属于两次出现（归属校验只确认能
451				// 归入某一次，不排除同时归入两次）。已失效且首次观测时间
452				// 已知的出现，首次观测不能晚于失效；下一次出现的首次观测
453				// 必须严格晚于上一次的失效时间——首次观测与失效两个端点都
454				// 接纳所在时刻的观测，相等即重叠。第 2 次及以后的出现必定
455				// 在上一次失效之后由本包创建，首次观测时间必须已知；只有
456				// 旧文件的第 1 次出现允许未知（无下界，不把零当作起点）。
457				// 这些检查针对保存的出现记录本身，与重叠范围内当前是否有
458				// 观测无关。
459				if !oj.Active && oj.HasFirstSeen && oj.FirstSeenTime > oj.InvalidTime {
460					return fmt.Errorf("%w: occurrence %d of landmark %s first seen at %d after invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, oj.InvalidTime)
461				}
462				if i > 0 {
463					if !oj.HasFirstSeen {
464						return fmt.Errorf("%w: occurrence %d of landmark %s lacks first seen time", ErrCorrupt, oj.Number, lm.ID)
465					}
466					// 上一次出现必已失效（仍有效且非最后一次已在上面拒绝）。
467					if prev := lm.Occurrences[i-1]; oj.FirstSeenTime <= prev.InvalidTime {
468						return fmt.Errorf("%w: occurrence %d of landmark %s starts at %d before previous invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, prev.InvalidTime)
469					}
470				}
471			}
472			if activeCount > 1 {
473				return fmt.Errorf("%w: multiple active occurrences for landmark %s", ErrCorrupt, lm.ID)
474			}
475		}
476		// 各路标历次出现的时间边界：来源帧的观测归属核对与校正记录路标列表
477		// 核对共用同一份边界、同一套归属规则（见 occurrence.go）。旧文件缺省
478		// sources（解码为 nil）时不构建，两处核对都不进行。
479		var bounds map[string][]occurrenceWindow
480		if len(fd.Sources) != 0 {
481			bounds = make(map[string][]occurrenceWindow, len(fd.Landmarks))
482			for _, lm := range fd.Landmarks {
483				bounds[lm.ID] = occurrenceWindowsOf(lm)
484			}
485		}
486		// 校验每条带逐帧依据的观测来源：观测路标必须存在，且所在帧时间必须
487		// 落入该路标某一次出现的时间边界（共享规则见 occurrence.go）。旧出现
488		// 已失效不代表其历史观测无效；同一标识两次出现之间（如 200 失效、
489		// 300 再现时的 250 帧）的观测没有归属，按损坏拒绝。null 帧来自缺少
490		// 逐帧依据的旧地图，其观测不在这里（也无法）核验；旧版平铺路标视为
491		// 一次无边界的有效出现，因此旧地图后来追加的来源帧仍按此规则检查。
492		if len(fd.Sources) != 0 {
493			// 归属校验的同时按（路标，出现编号）统计来源观测条数：每条观测
494			// 各算一次，同帧重复观测同一标识不去重，空观测帧不计。null 帧
495			// 缺少逐帧依据，其贡献已固定在出现的旧观测计数中，不在此统计，
496			// 也不能按帧数猜测。
497			tallies := make(map[string]map[int]int, len(fd.Landmarks))
498			for k, src := range fd.Sources {
499				if src == nil {
500					continue // 旧地图帧：无逐帧依据，不要求补齐归属
501				}
502				t := fd.Trajectory[k+1].Time
503				for _, ob := range src.Observations {
504					wins, ok := bounds[ob.ID]
505					if !ok {
506						return fmt.Errorf("%w: observation of unknown landmark %s at frame time %d", ErrCorrupt, ob.ID, t)
507					}
508					num := occurrenceNumberAt(wins, t)
509					if num == 0 {
510						return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, ob.ID, t)
511					}
512					c := tallies[ob.ID]
513					if c == nil {
514						c = make(map[int]int, 1)
515						tallies[ob.ID] = c
516					}
517					c[num]++
518				}
519			}
520			// 每次出现记录的观测次数必须等于归属该次出现的来源观测条数加上
521			// 该次出现已保存的旧观测贡献：偏多或偏少都是文件损坏。各次出现
522			// 分别核对，不能用另一次出现的观测补足；已失效的旧出现同样核对，
523			// 不因它不再参与区域查询而跳过。回环校正只改位置不改已接受观测
524			// 次数，正常校正后保存的文件仍满足此不变量。
525			for _, lm := range fd.Landmarks {
526				if len(lm.Occurrences) == 0 {
527					// 旧版平铺路标即第 1 次出现。
528					if got := tallies[lm.ID][1] + lm.LegacyCount; got != lm.Count {
529						return fmt.Errorf("%w: landmark %s records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, lm.Count, got)
530					}
531					continue
532				}
533				for _, oj := range lm.Occurrences {
534					if got := tallies[lm.ID][oj.Number] + oj.LegacyCount; got != oj.Count {
535						return fmt.Errorf("%w: landmark %s occurrence %d records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, oj.Number, oj.Count, got)
536					}
537				}
538			}
539	
540			// 位置核对：次数相符只说明观测“条数”对得上，还必须核对保存的路标
541			// 位置确实是这些观测依据当前保存位姿重放后的等权平均。每条来源观测
542			// 按所在帧当前保存的位姿转换到地图坐标，按帧时间升序、同帧按输入
543			// 次序，归入各自出现分别重放；同帧对同一标识的多条观测各自参与，
544			// 空观测帧不增加贡献。转换、接纳、增量平均与计数全部复用导入/校正
545			// 的同一规则（见 aggregate.go），旧文件固定旧贡献（LegacyCount 次
546			// 平均）作为聚合起点——不能当成零，也不能用缺少依据的帧数代替。
547			// 回环校正后保存的文件按当前轨迹重放即得到当前位置，不要求等于校正
548			// 记录里的历史快照；各次出现分别核对，已失效的出现同样核对。合并
549			// 距离只是导入/校正时的接纳门槛，不是保存位置偏差的容许范围：重放
550			// 中出现非有限结果或距离冲突，或最终平均位置与保存位置不完全一致，
551			// 都按损坏拒绝。纯旧文件没有 sources、null 旧帧没有依据，均不重放。
552			type posKey struct {
553				id  string
554				num int
555			}
556			posAggs := make(map[posKey]*observationAgg, len(fd.Landmarks))
557			seedPosAgg := func(id string, num, legacyCount int, lx, ly float64) {
558				a := &observationAgg{}
559				if legacyCount > 0 {
560					a.seed(legacyCount, lx, ly)
561				}
562				posAggs[posKey{id: id, num: num}] = a
563			}
564			for _, lm := range fd.Landmarks {
565				if len(lm.Occurrences) == 0 {
566					// 旧版平铺路标即第 1 次出现。
567					seedPosAgg(lm.ID, 1, lm.LegacyCount, lm.LegacyMX, lm.LegacyMY)
568					continue
569				}
570				for _, oj := range lm.Occurrences {
571					seedPosAgg(lm.ID, oj.Number, oj.LegacyCount, oj.LegacyMX, oj.LegacyMY)
572				}
573			}
574			for k, src := range fd.Sources {
575				if src == nil {
576					continue // 旧地图帧：无逐帧依据，其贡献固定在旧贡献起点中
577				}
578				pose := fd.Trajectory[k+1]
579				for _, ob := range src.Observations {
580					// 归属（存在性与时间边界）已在上面校验，num 必非 0。
581					num := occurrenceNumberAt(bounds[ob.ID], pose.Time)
582					a := posAggs[posKey{id: ob.ID, num: num}]
583					switch a.admit(pose, ob, fd.Config.MergeDistance) {
584					case obsNonFinite:
585						return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d is non-finite", ErrCorrupt, ob.ID, num, pose.Time)
586					case obsConflict:
587						return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d violates merge distance", ErrCorrupt, ob.ID, num, pose.Time)
588					}
589				}
590			}
591			checkPosition := func(id string, num int, x, y float64) error {
592				a := posAggs[posKey{id: id, num: num}]
593				// 次数核对已保证 a.count 与记录次数一致（含旧贡献起点），这里只
594				// 核对位置：保存位置必须与按依据重放出的等权平均完全一致。
595				if a.x != x || a.y != y {
596					return fmt.Errorf("%w: landmark %s occurrence %d is saved at (%v,%v) but its observations replay to (%v,%v)", ErrCorrupt, id, num, x, y, a.x, a.y)
597				}
598				return nil
599			}
600			for _, lm := range fd.Landmarks {
601				if len(lm.Occurrences) == 0 {
602					if err := checkPosition(lm.ID, 1, lm.X, lm.Y); err != nil {
603						return err
604					}
605					continue
606				}
607				for _, oj := range lm.Occurrences {
608					if err := checkPosition(lm.ID, oj.Number, oj.X, oj.Y); err != nil {
609						return err
610					}
611				}
612			}
613		}
614		segIDs := make(map[string]struct{}, len(fd.Segments))
615		for _, sg := range fd.Segments {
616			if sg.ID == "" || sg.Hash == "" {
617				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
618			}
619			if _, dup := segIDs[sg.ID]; dup {
620				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
621			}
622			segIDs[sg.ID] = struct{}{}
623		}
624		corrIDs := make(map[string]struct{}, len(fd.Corrections))
625		// corrOccKey 标识校正范围内被观测涉及的某个路标某一次出现。
626		type corrOccKey struct {
627			id  string
628			num int
629		}
630		for _, cr := range fd.Corrections {
631			if cr.ID == "" || cr.Anchor > cr.EndTime {
632				return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
633			}
634			// 锚点与结束时间必须准确命中已导入帧：trajectory[0] 是初始位姿，
635			// 不是可校正的帧，也不能用相邻帧的时间代替。轨迹时间已在前面
636			// 校验为严格递增，命中即唯一。
637			anchorIdx, endIdx := -1, -1
638			for j := 1; j < len(fd.Trajectory); j++ {
639				if fd.Trajectory[j].Time == cr.Anchor {
640					anchorIdx = j
641				}
642				if fd.Trajectory[j].Time == cr.EndTime {
643					endIdx = j
644				}
645			}
646			if anchorIdx < 0 || endIdx < 0 {
647				return fmt.Errorf("%w: correction %s range does not hit imported frames", ErrCorrupt, cr.ID)
648			}
649			// 记录必须恰好覆盖 [anchor, end] 内的每一帧：位姿条目数量等于
650			// 范围内帧数，按轨迹时间次序一一对应，且同一份前后位姿的时间
651			// 相同并就是对应帧的时间。缺失、重复、错序、额外加入范围外的
652			// 帧，或把前后时间写成两个不同帧，都使记录不能完整描述声明的
653			// 范围，按损坏拒绝。这里只核对覆盖的帧及时间：快照中的位置、
654			// 朝向和方差是提交时的历史值，不要求等于当前轨迹（后来对相同
655			// 范围再校正、或之后导入新帧，都不影响既有记录的合法性）。
656			if len(cr.Poses) != endIdx-anchorIdx+1 {
657				return fmt.Errorf("%w: correction %s does not cover every frame in its range", ErrCorrupt, cr.ID)
658			}
659			for i, pc := range cr.Poses {
660				ft := fd.Trajectory[anchorIdx+i].Time
661				if pc.Before.Time != ft || pc.After.Time != ft {
662					return fmt.Errorf("%w: correction %s pose entry %d does not match frame time %d", ErrCorrupt, cr.ID, i, ft)
663				}
664				if !finitePose(pc.Before) || !finitePose(pc.After) {
665					return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
666				}
667			}
668			for _, lc := range cr.Landmarks {
669				if lc.ID == "" {
670					return fmt.Errorf("%w: correction %s has empty landmark id", ErrCorrupt, cr.ID)
671				}
672				if lc.Occurrence < 0 || !isFinite(lc.Before.X) || !isFinite(lc.Before.Y) ||
673					!isFinite(lc.After.X) || !isFinite(lc.After.Y) ||
674					lc.Before.Count < 1 || lc.After.Count < 1 {
675					return fmt.Errorf("%w: correction %s has invalid landmark change", ErrCorrupt, cr.ID)
676				}
677			}
678			// 路标列表必须恰好描述记录范围（锚点帧到结束帧，两端包含；之后
679			// 追加的帧不属于范围）内逐帧观测实际涉及的路标出现：范围内被观测
680			// 到的每个（路标，出现编号）必须恰好有一条前后记录，同一次出现被
681			// 多帧或同帧多条观测涉及也只记一条；少记、多记、重复、或把出现
682			// 编号改指该范围没有涉及的另一出现，都按损坏拒绝整份文件，而不是
683			// 只看条目里的坐标与次数是否合法。归属沿用与来源校验相同的时间边
684			// 界规则：同一标识失效后再现属于不同出现，即使位置相同也分别对应；
685			// 已失效的旧出现只要范围内（含失效时刻）有它的观测就必须在列表
686			// 中，不因当前区域查询不再返回它而被排除；范围外帧（如记录之后
687			// 才再现的新出现）的观测不计入。范围内没有任何路标观测时列表必须
688			// 为空，非空即损坏。仅对范围内逐帧依据完整的校正做此核对：范围内
689			// 含 null 旧帧的校正缺少逐帧依据，保留旧地图的既有打开规则，不凭
690			// 推测要求补造观测。
691			if bounds != nil {
692				fullyBased := true
693				for k := anchorIdx - 1; k <= endIdx-1; k++ {
694					if fd.Sources[k] == nil {
695						fullyBased = false
696						break
697					}
698				}
699				if fullyBased {
700					want := make(map[corrOccKey]struct{})
701					for j := anchorIdx; j <= endIdx; j++ {
702						t := fd.Trajectory[j].Time
703						for _, ob := range fd.Sources[j-1].Observations {
704							// 归属已在上方的来源校验中确认（路标存在、必有唯一
705							// 接纳出现），这里同样计算以保持两处规则一致。
706							want[corrOccKey{id: ob.ID, num: occurrenceNumberAt(bounds[ob.ID], t)}] = struct{}{}
707						}
708					}
709					got := make(map[corrOccKey]struct{}, len(cr.Landmarks))
710					for _, lc := range cr.Landmarks {
711						num := lc.Occurrence
712						if num == 0 {
713							num = 1 // 更早版本写出的校正记录不带编号，按第 1 次出现解释
714						}
715						wins, ok := bounds[lc.ID]
716						if !ok || num < 1 || num > len(wins) {
717							return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d not touched by its range", ErrCorrupt, cr.ID, lc.ID, num)
718						}
719						key := corrOccKey{id: lc.ID, num: num}
720						if _, dup := got[key]; dup {
721							return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d more than once", ErrCorrupt, cr.ID, lc.ID, num)
722						}
723						got[key] = struct{}{}
724					}
725					for key := range want {
726						if _, ok := got[key]; !ok {
727							return fmt.Errorf("%w: correction %s misses landmark %s occurrence %d observed in its range", ErrCorrupt, cr.ID, key.id, key.num)
728						}
729					}
730					for key := range got {
731						if _, ok := want[key]; !ok {
732							return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d with no observation in its range", ErrCorrupt, cr.ID, key.id, key.num)
733						}
734					}
735				}
736			}
737			if _, dup := corrIDs[cr.ID]; dup {
738				return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
739			}
740			corrIDs[cr.ID] = struct{}{}
741		}
742		// 路标记录按标识索引，供失效记录与出现历史的交叉核对使用。
743		lmByID := make(map[string]*landmarkJSON, len(fd.Landmarks))
744		for i := range fd.Landmarks {
745			lmByID[fd.Landmarks[i].ID] = &fd.Landmarks[i]
746		}
747		invalIDs := make(map[string]struct{}, len(fd.Invalidations))
748		// invalTriples 记录每条失效操作实际引用的（操作标识，路标，出现编号）
749		// 三元组，供反向核对：每个已失效出现都必须是某条操作记录里的实际条目。
750		type invalTriple struct {
751			op  string
752			lm  string
753			num int
754		}
755		invalTriples := make(map[invalTriple]struct{}, len(fd.Invalidations))
756		for _, iv := range fd.Invalidations {
757			if iv.ID == "" || iv.Reason == "" || iv.Hash == "" || len(iv.Landmarks) == 0 {
758				return fmt.Errorf("%w: invalid invalidation record", ErrCorrupt)
759			}
760			if _, dup := invalIDs[iv.ID]; dup {
761				return fmt.Errorf("%w: duplicate invalidation %s", ErrCorrupt, iv.ID)
762			}
763			invalIDs[iv.ID] = struct{}{}
764			lmSeen := make(map[string]struct{}, len(iv.Landmarks))
765			for _, l := range iv.Landmarks {
766				if l.ID == "" || l.Occurrence < 1 {
767					return fmt.Errorf("%w: invalid invalidation landmark entry", ErrCorrupt)
768				}
769				if _, dup := lmSeen[l.ID]; dup {
770					return fmt.Errorf("%w: invalidation %s lists %s twice", ErrCorrupt, iv.ID, l.ID)
771				}
772				lmSeen[l.ID] = struct{}{}
773			}
774			// 交叉核对：成功失效结果里的每个（路标标识，出现编号）必须准确
775			// 指向该路标历史中同编号的那次出现，不能改指同一路标的其他出现，
776			// 也不能因为路标后来再次出现就把旧结果指向最新记录。被指出现必须
777			// 已经失效，且其上记录的失效操作标识、失效时间、失效原因都与这条
778			// 操作记录一致——时间与原因各自再合理也不够，实际由另一条操作撤下
779			// 时不能仅凭相同时间/原因认可。旧版平铺路标视为第 1 次有效出现，
780			// 不可能被失效记录引用（引用即损坏）。一条操作同时撤下多个路标时，
781			// 任意一个条目不满足对应关系都拒绝打开整个文件。
782			for _, l := range iv.Landmarks {
783				lm := lmByID[l.ID]
784				if lm == nil {
785					return fmt.Errorf("%w: invalidation %s result points to unknown landmark %s", ErrCorrupt, iv.ID, l.ID)
786				}
787				if len(lm.Occurrences) == 0 {
788					return fmt.Errorf("%w: invalidation %s result points to flat legacy landmark %s which has no invalidated occurrence", ErrCorrupt, iv.ID, l.ID)
789				}
790				if l.Occurrence > len(lm.Occurrences) {
791					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which does not exist", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
792				}
793				// 出现编号连续性已在上方路标校验中强制，该下标处编号即 l.Occurrence。
794				oj := lm.Occurrences[l.Occurrence-1]
795				if oj.Active {
796					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which is still active", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
797				}
798				if oj.InvalidOpID != iv.ID || oj.InvalidTime != iv.Time || oj.InvalidReason != iv.Reason {
799					return fmt.Errorf("%w: invalidation %s result for landmark %s occurrence %d does not match its saved invalidation (op %q, time %d, reason %q)", ErrCorrupt, iv.ID, l.ID, l.Occurrence, oj.InvalidOpID, oj.InvalidTime, oj.InvalidReason)
800				}
801				invalTriples[invalTriple{op: iv.ID, lm: l.ID, num: l.Occurrence}] = struct{}{}
802			}
803		}
804		// 反向核对：每个已失效出现都必须能在失效操作序列中找到引用同一（操作，
805		// 路标，出现编号）三元组的条目。正向核对已保证被引用出现的失效时间与
806		// 原因和引用方一致；此处堵住另一方向的矛盾：出现凭空携带失效信息、
807		// 声称撤下它的操作记录实际指向另一次出现，或两次出现声称被同一操作
808		// 撤下（一次操作对同一路标只会撤下当时唯一的有效出现）。旧地图没有
809		// 失效操作时，平铺路标视为有效、不携带失效信息，不会触发；旧地图后来
810		// 产生的失效操作同样在上述核对之列，不要求补齐原本缺失的逐帧观测。
811		for _, lm := range fd.Landmarks {
812			for _, oj := range lm.Occurrences {
813				if oj.Active {
814					continue
815				}
816				if _, ok := invalTriples[invalTriple{op: oj.InvalidOpID, lm: lm.ID, num: oj.Number}]; !ok {
817					return fmt.Errorf("%w: landmark %s occurrence %d is marked invalidated by operation %q which does not record that invalidation", ErrCorrupt, lm.ID, oj.Number, oj.InvalidOpID)
818				}
819			}
820		}
821		return nil
822	}
823	
824	func finitePose(p Pose) bool {
825		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
826	}
827	
828	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
829	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
830	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
831		h := sha256.New()
832		var b [8]byte
833		binary.BigEndian.PutUint64(b[:], uint64(anchor))
834		h.Write(b[:])
835		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
836			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
837			h.Write(b[:])
838		}
839		return fmt.Sprintf("%x", h.Sum(nil))
840	}
841	
842	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
843	func (m *Map) saveExclusive() error {
844		data, err := encodeFile(m.state)
845		if err != nil {
846			return err
847		}
848		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
849		if err != nil {
850			return err
851		}
852		return writeAndClose(f, data, m.path)
853	}
854	
855	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
856	func (m *Map) saveReplace() (err error) {
857		data, err := encodeFile(m.state)
858		if err != nil {
859			return err
860		}
861		dir, base := filepath.Split(m.path)
862		if dir == "" {
863			dir = "."
864		}
865		f, err := os.CreateTemp(dir, base+".tmp-*")
866		if err != nil {
867			return err
868		}
869		tmpName := f.Name()
870		// 任何失败路径都尽力清理临时文件。
871		defer func() {
872			if err != nil {
873				_ = os.Remove(tmpName)
874			}
875		}()
876		if err = writeAndClose(f, data, tmpName); err != nil {
877			return err
878		}
879		if err = os.Rename(tmpName, m.path); err != nil {
880			return err
881		}
882		return nil
883	}
884	
885	func writeAndClose(f *os.File, data []byte, name string) (err error) {
886		defer func() {
887			if cerr := f.Close(); err == nil {
888				err = cerr
889			}
890		}()
891		if _, err = f.Write(data); err != nil {
892			return err
893		}
894		if err = f.Sync(); err != nil {
895			return err
896		}
897		return nil
898	}
899	
900	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
901	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
902	func canonicalHash(frames []Frame) string {
903		h := sha256.New()
904		var lenBuf [4]byte
905		var numBuf [8]byte
906		putU32 := func(v uint32) {
907			binary.BigEndian.PutUint32(lenBuf[:], v)
908			h.Write(lenBuf[:])
909		}
910		putU64 := func(v uint64) {
911			binary.BigEndian.PutUint64(numBuf[:], v)
912			h.Write(numBuf[:])
913		}
914		putStr := func(s string) {
915			putU32(uint32(len(s)))
916			h.Write([]byte(s))
917		}
918	
919		putU32(uint32(len(frames)))
920		for _, fr := range frames {
921			putU64(uint64(fr.Time))
922			putU64(math.Float64bits(fr.DX))
923			putU64(math.Float64bits(fr.DY))
924			putU64(math.Float64bits(fr.DHeading))
925			putU64(math.Float64bits(fr.MoveVariance))
926			putU32(uint32(len(fr.Observations)))
927			for _, ob := range fr.Observations {
928				putStr(ob.ID)
929				putU64(math.Float64bits(ob.X))
930				putU64(math.Float64bits(ob.Y))
931			}
932		}
933		return fmt.Sprintf("%x", h.Sum(nil))
934	}
935

