194		m := newMap(t, baseConfig())
195	
196		// 先成功导入一段，制造既有状态。
197		good := Segment{ID: "g", Frames: []Frame{
198			{Time: 100, DX: 1, DY: 0, DHeading: 0, MoveVariance: 0.1,
199				Observations: []Observation{{ID: "K", X: 0, Y: 0}}},
200		}}
201		if _, err := m.ImportSegment(good); err != nil {
202			t.Fatal(err)
