204	
205		type tc struct {
206			name     string
207			seg      Segment
208			kind     string
209			frame    int
210			landmark string
211		}
212		cases := []tc{
213			{"empty batch", Segment{ID: "x"}, RejectEmptySegment, -1, ""},
214			{"empty segment id", Segment{Frames: []Frame{{Time: 1}}}, RejectEmptyID, -1, ""},
215			{"empty landmark id", Segment{ID: "x", Frames: []Frame{
216				{Time: 101, Observations: []Observation{{ID: ""}}},
217			}}, RejectEmptyID, 0, ""},
218			{"negative variance", Segment{ID: "x", Frames: []Frame{
219				{Time: 101, MoveVariance: -0.01},
220			}}, RejectNegativeVariance, 0, ""},
221			{"non-finite dx", Segment{ID: "x", Frames: []Frame{
222				{Time: 101, DX: math.NaN()},
223			}}, RejectNonFinite, 0, ""},
224			{"non-finite observation", Segment{ID: "x", Frames: []Frame{
225				{Time: 101, Observations: []Observation{{ID: "P", X: 0, Y: math.Inf(1)}}},
226			}}, RejectNonFinite, 0, "P"},
227			{"first frame not later than initial time", Segment{ID: "x", Frames: []Frame{
228				{Time: 0},
229			}}, RejectTimeOrder, 0, ""},
230			{"first frame not later than prev segment end", Segment{ID: "x", Frames: []Frame{
231				{Time: 100},
232			}}, RejectTimeOrder, 0, ""},
233			{"non strictly increasing", Segment{ID: "x", Frames: []Frame{
234				{Time: 101}, {Time: 101},
235			}}, RejectTimeOrder, 1, ""},
236			{"interval exceeded", Segment{ID: "x", Frames: []Frame{
237				{Time: 1102}, // 1102-100 = 1002 > 1000
238			}}, RejectInterval, 0, ""},
239			{"interval exceeded later frame", Segment{ID: "x", Frames: []Frame{
240				{Time: 101}, {Time: 1103},
241			}}, RejectInterval, 1, ""},
242			{"landmark conflict", Segment{ID: "x", Frames: []Frame{
243				{Time: 101, Observations: []Observation{{ID: "K", X: 10, Y: 10}}},
244			}}, RejectLandmarkConflict, 0, "K"},
245		}
246		for _, c := range cases {
247			t.Run(c.name, func(t *testing.T) {
248				_, err := m.ImportSegment(c.seg)
249				if err == nil {
