624			t.Fatalf("landmarks leaked after failed save: %v", lms)
625		}
626		// 段记录也回滚：恢复文件后同 ID 可正常导入。
627		if err := os.Remove(path); err != nil {
628			t.Fatal(err)
629		}
630		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{{Time: 100, DX: 1}}}); err != nil {
631			t.Fatalf("retry after failed save: %v", err)
632		}
633	}
