635	func TestClosedMap(t *testing.T) {
636		m := newMap(t, baseConfig())
637		if err := m.Close(); err != nil {
638			t.Fatal(err)
639		}
640		if _, err := m.CurrentPose(); !errors.Is(err, ErrClosed) {
641			t.Fatalf("current: %v", err)
